{"op":"add","path":"/root","value":"page"}
{"op":"add","path":"/elements/page","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg"},"children":["header","ledger"]}}
{"op":"add","path":"/elements/header","value":{"type":"ResultHeader","props":{"eyebrow":"Invoice extraction","title":"Your invoices, read and sorted","subtitle":"Amounts, dates and parties pulled from your document."},"children":[]}}
{"op":"add","path":"/elements/ledger","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg"},"repeat":{"statePath":"/result","key":"invoice_id"},"children":["entry"]}}
{"op":"add","path":"/elements/entry","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["entry-sep","id-line","entry-split"]}}
{"op":"add","path":"/elements/entry-sep","value":{"type":"Separator","props":{"orientation":"horizontal"},"children":[]}}
{"op":"add","path":"/elements/id-line","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"children":["issue-date","vendor-row","description"]}}
{"op":"add","path":"/elements/issue-date","value":{"type":"DateText","props":{"value":{"$item":"issue_date"},"style":"long","tone":"accent"},"children":[]}}
{"op":"add","path":"/elements/vendor-row","value":{"type":"Stack","props":{"direction":"horizontal","gap":"sm","align":"center"},"children":["vendor-heading","category-badge"]}}
{"op":"add","path":"/elements/vendor-heading","value":{"type":"Heading","props":{"text":{"$item":"vendor"},"level":"h2"},"children":[]}}
{"op":"add","path":"/elements/category-badge","value":{"type":"Badge","props":{"text":{"$item":"category/category"},"variant":"secondary"},"children":[]}}
{"op":"add","path":"/elements/description","value":{"type":"Text","props":{"text":{"$item":"description"},"variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/entry-split","value":{"type":"Split","props":{"ratio":"2:1","gap":"xl"},"children":["money-col","why-col"]}}
{"op":"add","path":"/elements/money-col","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["total-metric","tax-grid","details"]}}
{"op":"add","path":"/elements/total-metric","value":{"type":"Metric","props":{"label":"Total paid","value":{"$item":"amount_incl_tax"},"format":"decimal"},"children":[]}}
{"op":"add","path":"/elements/tax-grid","value":{"type":"Grid","props":{"columns":2,"gap":"sm"},"children":["net-fact","vat-fact"]}}
{"op":"add","path":"/elements/net-fact","value":{"type":"Fact","props":{"label":"Before tax","value":{"$item":"amount_excl_tax"}},"children":[]}}
{"op":"add","path":"/elements/vat-fact","value":{"type":"Fact","props":{"label":"VAT","value":{"$item":"vat_amount"}},"children":[]}}
{"op":"add","path":"/elements/details","value":{"type":"Stack","props":{"direction":"vertical","gap":"none"},"children":["d-invoice-number","d-order-id","d-time","d-vendor-address","d-siret","d-vendor-vat","d-billed-to","d-billing-address"]}}
{"op":"add","path":"/elements/d-invoice-number","value":{"type":"Detail","props":{"label":"Invoice no.","value":{"$item":"invoice_number"}},"children":[]}}
{"op":"add","path":"/elements/d-order-id","value":{"type":"Detail","props":{"label":"Order ID","value":{"$item":"invoice_id"}},"children":[]}}
{"op":"add","path":"/elements/d-time","value":{"type":"Detail","props":{"label":"Time","value":{"$item":"time"}},"children":[]}}
{"op":"add","path":"/elements/d-vendor-address","value":{"type":"Detail","props":{"label":"Vendor address","value":{"$item":"vendor_address"}},"children":[]}}
{"op":"add","path":"/elements/d-siret","value":{"type":"Detail","props":{"label":"SIRET","value":{"$item":"vendor_siret"}},"children":[]}}
{"op":"add","path":"/elements/d-vendor-vat","value":{"type":"Detail","props":{"label":"Vendor VAT no.","value":{"$item":"vendor_vat_number"}},"children":[]}}
{"op":"add","path":"/elements/d-billed-to","value":{"type":"Detail","props":{"label":"Billed to","value":{"$item":"company_name"}},"children":[]}}
{"op":"add","path":"/elements/d-billing-address","value":{"type":"Detail","props":{"label":"Billing address","value":{"$item":"company_address"}},"children":[]}}
{"op":"add","path":"/elements/why-col","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["why-heading","why-text","vat-rates","raw-collapsible"]}}
{"op":"add","path":"/elements/why-heading","value":{"type":"Heading","props":{"text":"Why it's filed this way","level":"h3"},"children":[]}}
{"op":"add","path":"/elements/why-text","value":{"type":"Text","props":{"text":{"$item":"category/explanation"},"variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/vat-rates","value":{"type":"MthdsResult","props":{"path":"vat_rates"},"children":[]}}
{"op":"add","path":"/elements/raw-collapsible","value":{"type":"Collapsible","props":{"title":"Show the raw text","defaultOpen":false},"children":["raw-text"]}}
{"op":"add","path":"/elements/raw-text","value":{"type":"Text","props":{"text":{"$item":"text"},"variant":"code"},"children":[]}}
